begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not (select prosecdef from pg_proc where oid='public.ops_state()'::regprocedure),'Public status wrapper is security invoker');
select ok(not (select prosecdef from pg_proc where oid='public.ops_backup_chunk(uuid,integer)'::regprocedure),'Public download wrapper is security invoker');
select ok(not has_function_privilege('authenticated','public.ops_backup_candidates(uuid)','execute'),'Browser cannot enumerate backup sources');
select ok(not has_function_privilege('authenticated','public.ops_backup_put(uuid,integer,text)','execute'),'Browser cannot write backup bytes');
select ok(not has_function_privilege('anon','public.ops_record_error(jsonb,text,text,text)','execute'),'Anonymous cannot bypass ingestion validation');
select ok(not has_table_privilege('authenticated','private.file_backup_chunks','select'),'Browser cannot read private binary rows');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in('file_backups','file_backup_chunks','operations_runs','client_errors','operations_limits','operations_alerts') and c.relrowsecurity and c.relforcerowsecurity),6::bigint,'All new tables force RLS');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"service_role","user_metadata":{"is_admin":true}}',true);
select is(public.ops_state()->>'status','denied','Forged admin claims cannot read operational data');
select is(public.ops_backup_chunk(gen_random_uuid(),0)->>'status','denied','Forged claims cannot download backups');
reset role;
create temp table fixture(run uuid,backup uuid,source text,sha text,raw bytea);
insert into fixture(run,raw) values(gen_random_uuid(),convert_to(repeat('a',1048576)||'end','UTF8'));
insert into private.operations_runs(id) select run from fixture;
insert into storage.objects(bucket_id,name,metadata) select 'scribe','operations-probe/'||run::text||'/backup-check.txt','{}'::jsonb from fixture;
update fixture set source=public.ops_probe_source(run),sha=encode(extensions.digest(raw,'sha256'),'hex');
grant all on fixture to service_role;
set local role service_role;
update fixture set backup=(public.ops_backup_begin(null,source,sha,octet_length(raw),run)->>'id')::uuid;
select ok((select backup is not null from fixture),'Service can start a protected copy');
select is(public.ops_backup_chunk((select backup from fixture),0)->>'status','not_found','Incomplete copies cannot be read');
select ok(not public.ops_backup_finish((select backup from fixture)),'Incomplete copies cannot be marked complete');
select ok(public.ops_backup_put((select backup from fixture),0,encode(convert_to(repeat('b',1048576),'UTF8'),'base64')),'First bounded chunk is accepted');
select ok(public.ops_backup_put((select backup from fixture),1,encode(convert_to('end','UTF8'),'base64')),'Last chunk is accepted');
select ok(not public.ops_backup_finish((select backup from fixture)),'Corruption fails the full checksum');
select ok(public.ops_backup_put((select backup from fixture),0,encode(convert_to(repeat('a',1048576),'UTF8'),'base64')),'Interrupted copy can be retried');
select ok(public.ops_backup_finish((select backup from fixture)),'Correct bytes complete the copy');
select ok(not public.ops_backup_put((select backup from fixture),0,encode(convert_to(repeat('b',1048576),'UTF8'),'base64')),'Completed bytes are immutable through worker RPC');
select is(public.ops_backup_begin(null,(select source from fixture),(select sha from fixture),1048579,(select run from fixture))->>'status','complete','Same snapshot is idempotent');
reset role;
delete from storage.objects where name=(select 'operations-probe/'||run::text||'/backup-check.txt' from fixture);
set local role service_role;
select is(decode(public.ops_backup_chunk((select backup from fixture),1)->>'data','base64'),convert_to('end','UTF8'),'Original Storage loss does not remove the protected bytes');
select is(public.ops_backup_chunk((select backup from fixture),0)->>'sha256',(select sha from fixture),'Recovery includes a verifiable full checksum');
select is(public.ops_record_error('{"kind":"test","name":"Error","route":"/setup/operations","frames":[]}'::jsonb,repeat('a',64),repeat('b',64),'unknown'),'recorded','Validated service telemetry is accepted');
select is(public.ops_record_error('{"kind":"test","name":"Error","route":"/setup/operations","frames":[]}'::jsonb,repeat('a',64),repeat('b',64),'unknown'),'recorded','Repeat events are grouped');
select is(public.ops_state()#>>'{errors,0,occurrences}','2','Grouped event retains its count');
select is(public.ops_alert_claim()->>'status','send','First error claims an alert');
select is(public.ops_alert_claim()->>'status','quiet','Concurrent alert attempt is held');
select is(public.ops_alert_claim(date_trunc('hour',now()))->>'status','ok','Successful delivery is recorded');
select is(public.ops_alert_claim()->>'status','quiet','Delivered alert is not sent again');
select public.ops_record_error('{"kind":"test"}'::jsonb,repeat('a',64),repeat('c',64),'unknown') from generate_series(1,30);
select is(public.ops_record_error('{"kind":"test"}'::jsonb,repeat('a',64),repeat('c',64),'unknown'),'limited','Per-network hourly cap is enforced in the database');
reset role;
select * from finish();
rollback;
